CREATE DATABASE IF NOT EXISTS library_management CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE library_management;
CREATE TABLE users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(150) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE categories (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL UNIQUE);
CREATE TABLE books (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(200) NOT NULL,author VARCHAR(150) NOT NULL,isbn VARCHAR(30) NOT NULL UNIQUE,category_id INT UNSIGNED NULL,quantity INT UNSIGNED NOT NULL DEFAULT 1,available_quantity INT UNSIGNED NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE SET NULL);
CREATE TABLE members (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,member_code VARCHAR(30) NOT NULL UNIQUE,name VARCHAR(120) NOT NULL,email VARCHAR(150) NOT NULL UNIQUE,phone VARCHAR(30),address VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE transactions (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,book_id INT UNSIGNED NOT NULL,member_id INT UNSIGNED NOT NULL,issued_at DATE NOT NULL,due_date DATE NOT NULL,returned_at DATE NULL,fine DECIMAL(10,2) NOT NULL DEFAULT 0,status ENUM('issued','returned') NOT NULL DEFAULT 'issued',FOREIGN KEY(book_id) REFERENCES books(id) ON DELETE RESTRICT,FOREIGN KEY(member_id) REFERENCES members(id) ON DELETE RESTRICT);
